package io.bmsride.monitor;
import android.app.*;import android.content.*;import android.os.*;import android.location.*;import org.json.*;import java.util.*;
@SuppressWarnings("MissingPermission") public class MonitorService extends Service implements Ble.Listener,LocationListener {
 final Handler h=new Handler(Looper.getMainLooper()); final Local binder=new Local(); Ble ble; Protocol.Battery battery; String status="未连接"; long gpsAt=0; double speed=Double.NaN,km=0,acc=Double.NaN; final GpsFilter gpsFilter=new GpsFilter(); LocationManager loc; final TripEnergy energy=new TripEnergy(); final RangeEstimate rangeEstimate=new RangeEstimate(); String rangeDevice=""; boolean gps=false; double capacityOverride=Double.NaN; final TripHistory history=new TripHistory(); 
 public class Local extends Binder{MonitorService service(){return MonitorService.this;}}
 public IBinder onBind(Intent i){return binder;}
 public void onCreate(){super.onCreate();capacityOverride=getSharedPreferences("bms",MODE_PRIVATE).getFloat("capacity",Float.NaN);ble=new Ble(this,this);loc=getSystemService(LocationManager.class);NotificationManager nm=getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("monitor","BMS 监测",NotificationManager.IMPORTANCE_LOW));h.post(loop);h.post(poll);}
 public int onStartCommand(Intent i,int flags,int id){Notification n=new Notification.Builder(this,"monitor").setSmallIcon(android.R.drawable.ic_menu_compass).setContentTitle("保锂安").setContentText("正在监测 · 点击打开").setContentIntent(PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE)).build();startForeground(1,n);ble.autoConnectLast();return START_NOT_STICKY;}
 public void status(String s){status=s;}public void data(Protocol.Battery b){battery=b;if(b==null)energy.breakInterval();}
 void enableGps(){if(gps)return;try{gps=true;loc.requestLocationUpdates(LocationManager.GPS_PROVIDER,0L,0f,this);}catch(Exception e){gps=false;invalidateGps();status="GPS 不可用: "+e.getMessage();}}
 void invalidateGps(){speed=Double.NaN;acc=Double.NaN;gpsAt=0;gpsFilter.reset();energy.breakInterval();}
 void disableGps(){loc.removeUpdates(this);gps=false;invalidateGps();}
 public void onLocationChanged(Location l){long now=SystemClock.elapsedRealtime();long at=l.getElapsedRealtimeNanos()/1000000L;if(!gps||!LocationManager.GPS_PROVIDER.equals(l.getProvider())||at<=0||at>now||now-at>GpsFilter.MAX_AGE_MS||at<=gpsAt)return;GpsFilter.Result r=gpsFilter.add(at,l.hasAccuracy()?l.getAccuracy():Double.NaN,l.hasSpeed()?l.getSpeed():Double.NaN,l.hasSpeedAccuracy()?l.getSpeedAccuracyMetersPerSecond():Double.NaN);if(!Double.isFinite(r.kmh)){invalidateGps();return;}speed=r.kmh;acc=l.getAccuracy();gpsAt=at;km+=r.meters/1000.0;history.observeSpeed(speed);}
 @Override public void onLocationChanged(java.util.List<Location> locations){for(Location l:locations)onLocationChanged(l);}
 public void onProviderEnabled(String p){}public void onProviderDisabled(String p){if(LocationManager.GPS_PROVIDER.equals(p))invalidateGps();}public void onStatusChanged(String p,int s,Bundle b){}
 void resetTrip(){snapshot();history.clear();energy.clear();km=0;invalidateGps();}
 void setCapacity(double ah){capacityOverride=ah;getSharedPreferences("bms",MODE_PRIVATE).edit().putFloat("capacity",(float)ah).apply();}
 static Object num(double x){return Double.isFinite(x)?x:JSONObject.NULL;}
 JSONObject snapshot(){long now=System.currentTimeMillis();Protocol.Battery b=battery;boolean valid=b!=null&&now>=b.time&&now-b.time<=5000;boolean g=gps&&gpsAt>0&&SystemClock.elapsedRealtime()>=gpsAt&&SystemClock.elapsedRealtime()-gpsAt<=GpsFilter.MAX_AGE_MS&&Double.isFinite(speed);double eff=energy.efficiency();double ah=valid?(Double.isFinite(b.ah)?b.ah:capacityOverride*b.soc/100):Double.NaN;String active=ble.g==null?"":ble.g.getDevice().getAddress();if(!active.isEmpty()&&!active.equals(rangeDevice)){if(!rangeDevice.isEmpty()){rangeEstimate.clear();energy.clear();eff=Double.NaN;}rangeDevice=active;}double range=rangeEstimate.update(valid?b.voltage:Double.NaN,ah,eff);try{JSONObject j=new JSONObject();j.put("bmsValid",valid).put("gpsValid",g).put("soc",valid?num(b.soc):JSONObject.NULL).put("voltage",valid?num(b.voltage):JSONObject.NULL).put("current",valid?num(b.current):JSONObject.NULL).put("power",valid?num(b.voltage*b.current):JSONObject.NULL).put("ah",num(ah)).put("mos",valid?num(b.mos):JSONObject.NULL).put("delta",valid?num(b.delta()):JSONObject.NULL).put("speed",g?num(speed):JSONObject.NULL).put("km",num(km)).put("eff",num(eff)).put("range",num(range)).put("rangeCurrent",rangeEstimate.current()).put("accuracy",g?num(acc):JSONObject.NULL);JSONArray a=new JSONArray();if(valid)for(double c:b.cells)a.put(c);j.put("cells",a).put("maxSpeed",num(history.maxSpeed()));JSONArray ts=new JSONArray();if(valid)for(double t:b.temps)ts.put(num(t));j.put("temps",ts).put("mosFlags",valid&&b.mosFlags>=0?b.mosFlags:JSONObject.NULL).put("alarm",valid&&b.alarm!=null?b.alarm:JSONObject.NULL).put("protection",valid&&b.protection!=null?b.protection:JSONObject.NULL).put("fault",valid&&b.fault!=null?b.fault:JSONObject.NULL);return j;}catch(Exception ex){return new JSONObject();}}
 final Runnable poll=new Runnable(){public void run(){ble.tick();h.postDelayed(this,500);}};
 final Runnable loop=new Runnable(){public void run(){long now=System.currentTimeMillis(),at=SystemClock.elapsedRealtime();boolean gv=gps&&gpsAt>0&&at>=gpsAt&&at-gpsAt<=GpsFilter.MAX_AGE_MS&&Double.isFinite(speed);boolean bv=battery!=null&&now>=battery.time&&now-battery.time<=5000;double watts=bv?Math.max(0,-battery.voltage*battery.current):Double.NaN;energy.add(at,km,gv?watts:Double.NaN);JSONObject sample=snapshot();history.add(at,sample.optDouble("speed",Double.NaN),gv&&bv?sample.optDouble("eff",Double.NaN):Double.NaN);h.postDelayed(this,1000);}};
 public void onDestroy(){h.removeCallbacksAndMessages(null);ble.close();disableGps();super.onDestroy();}
}
